import {applyStress,affordability,netWorth} from './model.js';
import {projectPlan} from './planning.js';
import {budgetSummary} from './budget.js';
import {COACH_DEFAULTS} from './coach-settings.js';
const dollars=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
export function diagnose(state,{housing=state.budget?.housing??'current'}={}){
 const settings={...COACH_DEFAULTS,...state.coachSettings},homeMode=['backward','forward'].includes(state.mode),h=homeMode?applyStress(state.home,state.stress):state.home,a=affordability(h),b=budgetSummary(h,state.budget),n=netWorth(state.worth),worthMode=state.mode==='worth';
 const future=worthMode&&state.worthView==='future',p=future?projectPlan(state):null;
 const findings=[],add=(id,severity,title,detail,action,rule='Plan check')=>findings.push({id,severity,title,detail,action,rule});
 const reviewed=['householdGrossAnnual','homePrice','availableCash','car1Payment','car2Payment','groceries'].some(k=>state.provenance?.home?.[k])||(state.mode==='budget'&&state.provenance?.budget?.currentHousing);
 const example=!worthMode&&!reviewed;
 const hasFutureCashFlows=future&&((state.planning?.employerMatchMonthly??0)>0||state.planning?.useBudgetSavings||state.worth.withdrawalMonthly>0||[...state.worth.cash,...state.worth.investments].some(r=>r.monthly>0));
 if(worthMode&&n.assets===0&&n.liabilities===0&&!hasFutureCashFlows)return {mood:'neutral',quote:'Give me the whole picture.',findings:[],intro:'Enter current asset values and debt balances first. An empty worksheet is not a financial diagnosis.',example:false};
 if(homeMode&&h.homePrice===0)return {mood:'neutral',quote:'Give the plan a destination.',findings:[],intro:'Enter a desired home price to check its monthly cost and upfront cash.',example};
 if(worthMode){
  if(p?.end.unfunded>0)add('unfunded',3,'The forecast runs out of spendable money',`${dollars(p.end.unfunded)} of planned withdrawals cannot be funded by cash and investments. Property is not sold automatically.`,{mode:'worth',field:'p-withdrawalMonthly'});
  if(p?.fundingPoints.some(f=>f.shortfall>.01)){const first=p.fundingPoints.find(f=>f.shortfall>.01);add('forecast-funding',3,'The forecast needs more funding',`At age ${h.age+first.year}, planned contributions and debt payments exceed the selected Budget funding by ${dollars(first.shortfall)} per month. The projection assumes this money is available; it does not silently reduce contributions.`,{mode:'worth',field:'planning-useBudgetSavings',future:true});}
  const growing=state.worth.debts.filter(d=>d.value>0&&d.payment<d.value*d.rate/1200);
  if(growing.length)add('growing-debt',future?3:1,future?'These payments do not cover interest':'Check the debt-payment assumptions',growing.map(d=>`${d.name}: with the entered payment of ${dollars(d.payment)}, at least ${dollars(d.value*d.rate/1200-d.payment)} more per month is needed just to cover initial interest`).join('; ')+'. Verify the contractual annual interest rate and payment in the future worksheet; zero payments may simply be unfinished entries.',{mode:'worth',section:'section-07',future:true});
  if(n.total<0)add('negative-worth',2,'Debt exceeds the assets entered',`The current gap is ${dollars(-n.total)}. Check that every asset and debt is listed, then prioritize a repayment plan.`,{mode:'worth',section:'section-07'});
  if(p&&p.end.real<n.total)add('real-decline',1,'The forecast loses purchasing power',`At age ${h.age+state.worth.years}, net worth is ${dollars(p.end.real)} in today's dollars, compared with ${dollars(n.total)} now.`,{mode:'worth',field:'p-inflation',future:true});
  if(p&&state.worth.years>40)add('long-forecast',1,'That is a long-range illustration',`${state.worth.years} years of fixed returns and unchanged spending is a scenario, not a prediction. Try a nearer age and less optimistic returns.`,{mode:'worth',field:'p-targetAge',future:true});
 }else{
  const remaining=homeMode?a.bufferAtTarget:housing==='proposed'?b.proposedRemaining:b.currentRemaining;
  if(remaining<-.01)add('shortfall',3,'This month does not balance',`The ${homeMode||housing==='proposed'?'proposed-home':'current-housing'} plan is short ${dollars(-remaining)} per month before any extra cushion. Review the largest costs first.`,{mode:'budget',section:'section-04'});
  if((homeMode||housing==='proposed')&&a.cashGap>.01)add('cash-gap',3,'The purchase needs more upfront cash',`The target needs ${dollars(a.cashGap)} more for its down payment, closing costs and protected reserve. A lower price or more purchase savings changes this gap.`,{mode:'backward',field:'h-availableCash'});
  const cars=h.car1Payment+h.car2Payment,carLimit=Math.max(0,a.takeHome)*settings.carPaymentPct/100;
  if(cars>carLimit+.01&&cars>0)add('car-payments',3,'Those car payments are eating the paycheck',`${dollars(cars)} per month is ${a.takeHome>0?(cars/a.takeHome*100).toFixed(1)+'% of modeled take-home':'unfunded by modeled take-home'}. Your adjustable ${settings.carPaymentPct}% coach threshold is ${dollars(carLimit)}. This threshold is an app preference, not a Ramsey rule.`,{mode:'budget',section:'section-05'},'Adjustable coach threshold');
  if(remaining>=-.01&&remaining<h.monthlyBuffer-.01)add('thin-buffer',2,'Give the plan more breathing room',`${dollars(remaining)} remains; you chose ${dollars(h.monthlyBuffer)}. Another ${dollars(h.monthlyBuffer-remaining)} per month would meet that cushion.`,{mode:'budget',section:'section-04'});
 }
 if(settings.ramsey){
  const consumer=worthMode?state.worth.debts.filter(d=>d.id!=='mortgage'&&d.value>0):[];
  if(worthMode&&consumer.length)add('consumer-debt',1,'Dave would focus on consumer debt',`The non-mortgage entries total ${dollars(consumer.reduce((s,d)=>s+d.value,0))}. Ramsey favors smallest-balance-first repayment; highest-rate-first generally minimizes interest when other terms are equal. Verify which entries are mortgages.`,{mode:'worth',section:'section-07'},'Ramsey preference');
  else if(!worthMode&&h.car1Payment+h.car2Payment+h.otherDebtPayment>0)add('consumer-payments',1,'Dave is no fan of consumer payments',`${dollars(h.car1Payment+h.car2Payment+h.otherDebtPayment)} goes to non-housing debt each month. Balances and contractual interest rates in Net worth are needed to evaluate payoff, rather than guessing from payments.`,{mode:'budget',section:'section-05'},'Ramsey preference');
  if(homeMode&&h.homePrice>0){const mortgagePayment=a.target.pi+a.target.tax+a.target.insurance+a.target.hoa+a.target.pmi;if(a.target.loan>0&&(h.loanTermYears>15||mortgagePayment>a.takeHome*.25))add('ramsey-home',1,'Dave’s mortgage preference is stricter',`Ramsey favors a 15-year fixed loan with the housing payment at most 25% of take-home. This target is ${h.loanTermYears} years and ${a.takeHome>0?(mortgagePayment/a.takeHome*100).toFixed(1)+'%':'not supported by take-home'}. Maintenance and utilities still matter separately. Your main result uses your own spending plan.`,{mode:'backward',section:'section-02'},'Ramsey preference');}
  if(worthMode&&h.householdGrossAnnual>0&&n.groups.vehicles>h.householdGrossAnnual*.5)add('vehicle-value',1,'A lot of income is parked in vehicles',`Entered vehicles total ${dollars(n.groups.vehicles)}. Ramsey's comparison is half of annual income (${dollars(h.householdGrossAnnual*.5)}), not half of net worth. Confirm the income in your home worksheet.`,{mode:'worth',section:'section-04'},'Ramsey preference');
 }
 if(worthMode){const cash=state.worth.cash.find(x=>x.id==='emergency')?.value,essentials=b.currentHousing+b.essential+b.debt;
  if((cash??0)===0&&essentials>0)add('missing-emergency',1,'An emergency reserve is not identified',`The emergency-fund row is zero or missing. That may be unfinished data, or your reserve may sit in another account. Identify the cash you would use for emergencies; the coach target is ${settings.emergencyMonths} months of current housing, essentials and debt payments from Budget. Count each dollar once.`,{mode:'worth',section:'section-01'},'Data to confirm');
  if(cash>0&&essentials>0&&cash<essentials*settings.emergencyMonths)add('emergency',1,'Check the emergency cushion',`${dollars(cash)} is about ${(cash/essentials).toFixed(1)} months of current housing, essentials and debt payments from Budget. Your coach target is ${settings.emergencyMonths} months; confirm that Budget describes your household.`,{mode:'worth',field:'w-cash-emergency-value'},'Adjustable coach threshold');
 }
 findings.sort((x,y)=>y.severity-x.severity);
 const inactiveTax=h.taxMode===1?['incomeTaxRate','payrollTaxRate',...(h.filingStatus===1?[]:['wageEarners','secondEarnerPct']),...(h.wageEarners===0?['secondEarnerPct']:[])]:['filingStatus','wageEarners','secondEarnerPct','stateTaxRate'];
 const exampleCount=worthMode?0:Object.keys(state.home).filter(k=>k!=='age'&&!inactiveTax.includes(k)&&!state.provenance?.home?.[k]).length;
 const severe=findings.some(f=>f.severity===3),caution=findings.length>0;
 return {mood:example?'neutral':severe?'angry':caution?'concerned':'happy',quote:example?'Let’s make these your numbers.':severe?'GOOD GOD!':caution?'Let’s give this a closer look.':'Now that’s a plan with some room!',example,findings,intro:example?'These are starting examples, not a judgment about you.':future?`Reviewing the forecast to age ${h.age+state.worth.years}, plus the starting balances.`:worthMode?'Reviewing the balances entered, not your age or personal worth.':`Reviewing ${homeMode?'the target home':housing==='proposed'?'Budget with proposed ownership':'Budget with current housing'}. ${homeMode&&state.stress.enabled?'Stress test is on.':''}`,positive:worthMode?`No flagged balance or forecast constraint was found in the entries reviewed. Confirm all balances, returns and future spending.`:`This plan meets its selected monthly cushion${homeMode||housing==='proposed'?' and the purchase cash check':''}. It is not a lender approval or a guarantee.`,exampleCount};
}
